mapper.select:
SELECT o.*,
       u.user_name AS userName,
       u.phonenumber
FROM furniture_order o
LEFT JOIN sys_user u ON o.user_id = u.user_id


        AND o.order_no = #{orderNo}


        AND o.user_id = #{userId}


        AND o.package_id = #{packageId}


        AND o.pay_status = #{payStatus}


ORDER BY o.id DESC
